  <script>
    const categories = ["Top", "Trending", "Watchlist", "Prediction Markets", "Most Visited", "New"];
    const networks = ["All Networks", "BSC", "Solana", "Base", "Ethereum", "More"];

    const baseCoins = [
      {name:"Bitcoin",sym:"BTC",price:75612.78,mcap:1510000000000,vol:42300000000,supply:"20.01M BTC",color:"#f7931a"},
      {name:"Ethereum",sym:"ETH",price:2356.00,mcap:284350000000,vol:19800000000,supply:"120.36M ETH",color:"#627eea"},
      {name:"Tether",sym:"USDT",price:1.00,mcap:102000000000,vol:83200000000,supply:"102.1B USDT",color:"#26a17b"},
      {name:"BNB",sym:"BNB",price:612.33,mcap:89200000000,vol:1920000000,supply:"145.88M BNB",color:"#f3ba2f"},
      {name:"Solana",sym:"SOL",price:172.85,mcap:78100000000,vol:4200000000,supply:"451.8M SOL",color:"#14f195"},
      {name:"USD Coin",sym:"USDC",price:1.00,mcap:33100000000,vol:10200000000,supply:"33.1B USDC",color:"#2775ca"},
      {name:"XRP",sym:"XRP",price:0.62,mcap:35600000000,vol:1700000000,supply:"57.0B XRP",color:"#23292f"},
      {name:"Dogecoin",sym:"DOGE",price:0.18,mcap:26200000000,vol:1140000000,supply:"145.5B DOGE",color:"#c2a633"},
      {name:"Toncoin",sym:"TON",price:6.12,mcap:21300000000,vol:310000000,supply:"3.47B TON",color:"#0098ea"},
      {name:"Cardano",sym:"ADA",price:0.45,mcap:15800000000,vol:440000000,supply:"35.2B ADA",color:"#0033ad"},
      {name:"TRON",sym:"TRX",price:0.12,mcap:10400000000,vol:560000000,supply:"88.9B TRX",color:"#ff0013"},
      {name:"Avalanche",sym:"AVAX",price:33.88,mcap:13800000000,vol:690000000,supply:"407.3M AVAX",color:"#e84142"},
      {name:"Shiba Inu",sym:"SHIB",price:0.000028,mcap:16500000000,vol:1030000000,supply:"589.2T SHIB",color:"#f28b36"},
      {name:"Polkadot",sym:"DOT",price:8.14,mcap:12100000000,vol:370000000,supply:"1.48B DOT",color:"#e6007a"},
      {name:"Chainlink",sym:"LINK",price:18.27,mcap:10700000000,vol:590000000,supply:"587.1M LINK",color:"#2a5ada"},
      {name:"Litecoin",sym:"LTC",price:88.25,mcap:6600000000,vol:520000000,supply:"74.8M LTC",color:"#345c9c"}
    ];

    const categoriesByIdx = categories.reduce((acc, c, i) => (acc[c] = i, acc), {});
    const networkByIdx = networks.reduce((acc, n, i) => (acc[n] = i, acc), {});

    function seeded(index) { return Math.abs(Math.sin(index * 17.11) * 10000) % 1; }
    function pct(index, scale=5) { return (seeded(index) * scale * 2 - scale); }
    function money(n) { return `$${n.toLocaleString(undefined,{maximumFractionDigits:n>=1?2:6,minimumFractionDigits:n>=1?2:2})}`; }
    function big(n) {
      if (n >= 1e12) return `$${(n/1e12).toFixed(2)}T`;
      if (n >= 1e9) return `$${(n/1e9).toFixed(2)}B`;
      if (n >= 1e6) return `$${(n/1e6).toFixed(2)}M`;
      return `$${n.toLocaleString()}`;
    }

    const allCoins = Array.from({length:8400}).map((_,i)=>{
      const b = baseCoins[i % baseCoins.length];
      const rank = i+1;
      const drift = 1 + ((i<16?0:((seeded(i)-0.5)*0.8)));
      return {
        rank,
        name: i<16 ? b.name : `${b.name} ${Math.floor(i/16)+1}`,
        sym: i<16 ? b.sym : `${b.sym}${Math.floor(i/16)+1}`,
        price: b.price * drift,
        h1: pct(i+1,1.8),
        h24: pct(i+2,5),
        d7: pct(i+3,14),
        mcap: b.mcap * drift * (i<16?1:0.08 + seeded(i)*0.25),
        vol: b.vol * (0.1 + seeded(i+4)*1.5),
        supply: b.supply,
        color: b.color,
        category: categories[i % categories.length],
        network: networks[(i+2) % networks.length === 5 ? 0 : (i+2) % networks.length],
        sparkSeed: i+7
      }
    });

    let activeCategory = "Top";
    let activeNetwork = "All Networks";
    let page = 1;
    let rowsPerPage = 100;

    const visibleCols = {price:true,h1:true,h24:true,d7:true,mcap:true,vol:true,supply:true,spark:true};

    const categoryTabs = document.getElementById('categoryTabs');
    const networkTabs = document.getElementById('networkTabs');
    const tableBody = document.getElementById('tableBody');
    const pagination = document.getElementById('pagination');

    function tabBtn(label, active, onClick){
      const b = document.createElement('button');
      b.className = 'tab' + (active ? ' active':'');
      b.textContent = label;
      b.onclick = onClick;
      return b;
    }

    function renderTabs(){
      categoryTabs.innerHTML = '';
      networkTabs.innerHTML = '';
      categories.forEach(c=>categoryTabs.appendChild(tabBtn(c,c===activeCategory,()=>{activeCategory=c; page=1; render();})));
      networks.forEach(n=>networkTabs.appendChild(tabBtn(n,n===activeNetwork,()=>{activeNetwork=n; page=1; render();})));
    }

    function filtered(){
      return allCoins.filter(c=>{
        const cat = activeCategory === 'Top' ? true : c.category === activeCategory;
        const net = activeNetwork === 'All Networks' ? true : c.network === activeNetwork;
        const gainers = document.getElementById('onlyGainers').checked ? c.h24 > 0 : true;
        const hv = document.getElementById('highVolume').checked ? c.vol > 1e9 : true;
        const lc = document.getElementById('largeCap').checked ? c.mcap > 1e10 : true;
        return cat && net && gainers && hv && lc;
      });
    }

    function spark(seed, up){
      let d = '';
      for(let i=0;i<24;i++){
        const x = i * 5;
        const y = 17 + Math.sin((seed+i)*0.8)*7 + (up? -i*0.08 : i*0.08);
        d += (i===0?`M${x},${y}`:` L${x},${y}`);
      }
      return `<svg class="spark" viewBox="0 0 120 34" aria-hidden="true"><path d="${d}" fill="none" stroke="${up ? '#16c784' : '#ea3943'}" stroke-width="2"/></svg>`;
    }

    function td(content, cls=''){ const cell=document.createElement('td'); if(cls) cell.className=cls; cell.innerHTML=content; return cell; }

    function renderTable(rows){
      tableBody.innerHTML = '';
      rows.forEach(r=>{
        const tr = document.createElement('tr');
        tr.appendChild(td(r.rank,'rank'));
        tr.appendChild(td(`<div class="coin"><span class="dot" style="background:${r.color}"></span><strong>${r.name}</strong><span class="symbol">${r.sym}</span></div>`));
        tr.appendChild(td(money(r.price),'num col-price'));
        tr.appendChild(td(`<span class="${r.h1>=0?'up':'down'}">${r.h1>=0?'+':''}${r.h1.toFixed(2)}%</span>`,'num col-h1'));
        tr.appendChild(td(`<span class="${r.h24>=0?'up':'down'}">${r.h24>=0?'+':''}${r.h24.toFixed(2)}%</span>`,'num col-h24'));
        tr.appendChild(td(`<span class="${r.d7>=0?'up':'down'}">${r.d7>=0?'+':''}${r.d7.toFixed(2)}%</span>`,'num col-d7'));
        tr.appendChild(td(big(r.mcap),'num col-mcap'));
        tr.appendChild(td(big(r.vol),'num col-vol'));
        tr.appendChild(td(r.supply,'num col-supply'));
        tr.appendChild(td(spark(r.sparkSeed, r.d7>=0),'col-spark'));
        tableBody.appendChild(tr);
      });
    }

    function renderPagination(total){
      const totalPages = Math.max(1,Math.ceil(total/rowsPerPage));
      if(page>totalPages) page=totalPages;
      pagination.innerHTML = '';
      const pages = [1,2,3,4,totalPages].filter((v,i,a)=>a.indexOf(v)===i && v<=totalPages);
      pages.forEach(p=>{
        const el = document.createElement('button');
        el.className = 'page'+(p===page?' active':'');
        el.textContent = p;
        el.onclick = ()=>{page=p; render();};
        pagination.appendChild(el);
      });
    }

    function applyColumnVisibility(){
      Object.keys(visibleCols).forEach(k=>{
        document.querySelectorAll('.col-'+k+', th[data-col="'+k+'"]').forEach(el=>{
          el.style.display = visibleCols[k] ? '' : 'none';
        });
      });
    }

    function buildColumnChecks(){
      const host = document.getElementById('columnChecks');
      const labels = {price:'Price',h1:'1h %',h24:'24h %',d7:'7d %',mcap:'Market Cap',vol:'Volume(24h)',supply:'Circulating Supply',spark:'7d Sparkline'};
      host.innerHTML = '';
      Object.keys(labels).forEach(k=>{
        const label = document.createElement('label');
        label.innerHTML = `<input type="checkbox" ${visibleCols[k]?'checked':''}/> ${labels[k]}`;
        label.querySelector('input').onchange = (e)=>{visibleCols[k]=e.target.checked; applyColumnVisibility();};
        host.appendChild(label);
      });
    }

    function render(){
      renderTabs();
      const rows = filtered();
      const start = (page-1)*rowsPerPage;
      renderTable(rows.slice(start,start+rowsPerPage));
      renderPagination(rows.length);
      document.getElementById('resultCount').textContent = `${rows.length.toLocaleString()} assets`;
      applyColumnVisibility();
    }

    document.getElementById('toggleColumns').onclick = ()=>document.getElementById('columnsPanel').classList.toggle('show');
    document.getElementById('toggleFilters').onclick = ()=>document.getElementById('filtersPanel').classList.toggle('show');
    ['onlyGainers','highVolume','largeCap'].forEach(id=>document.getElementById(id).addEventListener('change',()=>{page=1;render();}));
    document.getElementById('readMore').onclick = ()=>document.getElementById('moreText').classList.toggle('show');

    const promos = [
      ['Institutional-Grade Alerts Now Live','Set custom market cap and volatility triggers powered by CoinTracker AI.'],
      ['New: Network-Specific Heatmaps','Compare momentum across Ethereum, Solana, BSC, and Base in one click.'],
      ['Pro Watchlists Updated','Track cross-exchange liquidity shifts and whale activity in real-time.']
    ];
    let promoIdx = 0;
    function showPromo(){
      document.getElementById('promoTitle').textContent = promos[promoIdx][0];
      document.getElementById('promoBody').textContent = promos[promoIdx][1];
    }
    document.getElementById('prevPromo').onclick = ()=>{promoIdx=(promoIdx+promos.length-1)%promos.length;showPromo();};
    document.getElementById('nextPromo').onclick = ()=>{promoIdx=(promoIdx+1)%promos.length;showPromo();};
    setInterval(()=>{promoIdx=(promoIdx+1)%promos.length;showPromo();},5000);

    buildColumnChecks();
    render();
  </script>
</body>
</html>
EOF

